"""HTTP-only phpMyAdmin client and same-origin response adaptation."""

from __future__ import annotations

import http.client
import re
from collections.abc import Iterator
from datetime import UTC, datetime
from email.utils import parsedate_to_datetime
from http.cookies import SimpleCookie
from urllib.parse import urlencode, urlsplit

from fastapi.responses import Response, StreamingResponse

from systutor.core.errors import AppError

TEXT_TYPES = (
    "text/html",
    "text/css",
    "application/javascript",
    "text/javascript",
    "application/json",
)
HOP = {
    "connection",
    "keep-alive",
    "proxy-authenticate",
    "proxy-authorization",
    "te",
    "trailer",
    "transfer-encoding",
    "upgrade",
    "host",
    "content-length",
}
LIMIT = 2 * 1024 * 1024


def validate_url(value: str) -> str:
    try:
        parsed = urlsplit(value)
        _ = parsed.port
    except ValueError as exc:
        raise AppError(
            "URL interna inválida", status_code=409, code="hosting_phpmyadmin_unavailable"
        ) from exc
    if (
        parsed.scheme not in ("http", "https")
        or not parsed.hostname
        or parsed.username
        or parsed.password
        or parsed.query
        or parsed.fragment
    ):
        raise AppError(
            "phpMyAdmin interno no configurado",
            status_code=409,
            code="hosting_phpmyadmin_unavailable",
        )
    return value.rstrip("/")


def merge_cookies(cookies: dict[str, str], headers: list[tuple[str, str]]) -> dict[str, str]:
    merged = cookies.copy()
    for name, value in headers:
        if name.lower() != "set-cookie":
            continue
        jar = SimpleCookie()
        try:
            jar.load(value)
        except Exception:
            continue
        for key, morsel in jar.items():
            expired = morsel["max-age"] == "0"
            if morsel["expires"]:
                try:
                    expired |= parsedate_to_datetime(morsel["expires"]) <= datetime.now(UTC)
                except (ValueError, TypeError):
                    pass
            if expired or not morsel.value:
                merged.pop(key, None)
            else:
                merged[key] = morsel.value
    return merged


def is_login(body: bytes) -> bool:
    return bool(
        re.search(rb"<input\b[^>]*\bname\s*=\s*['\"]pma_password['\"]", body, re.I)
        and re.search(rb"<input\b[^>]*\bname\s*=\s*['\"]pma_username['\"]", body, re.I)
    )


def remove_frame_breakout(html: str) -> str:
    """phpMyAdmin's frame guard hides the page and navigates the top window.

    This is only applied to authenticated proxied HTML. The standalone
    phpMyAdmin deployment retains its own framing protection.
    """
    html = re.sub(
        r'<style\b[^>]*\bid=["\']cfs-style["\'][^>]*>.*?</style\s*>',
        "",
        html,
        flags=re.I | re.S,
    )
    return re.sub(
        r'<script\b[^>]*\bsrc=["\'][^"\']*\bcross_framing_protection\.js(?:\?[^"\']*)?["\'][^>]*>\s*</script\s*>',
        "",
        html,
        flags=re.I | re.S,
    )


def rewrite(value: str, internal: str, legacy: str, proxy: str) -> str:
    """Replace known absolute origins and their base paths, plus root-relative URLs."""
    sources = [internal, legacy]
    for source in sources:
        parsed = urlsplit(source)
        if parsed.scheme in ("http", "https") and parsed.netloc:
            origin = f"{parsed.scheme}://{parsed.netloc}"
            prefix = parsed.path.rstrip("/")
            value = value.replace(origin + prefix + "/", proxy + "/")
            value = value.replace(origin + prefix + "?", proxy + "/?")
            value = value.replace(origin + prefix + '"', proxy + '/"')
    value = re.sub(
        r"https?://(?:127\.0\.0\.1|localhost)(?::\d+)?(?=/|\?|\b)", proxy, value, flags=re.I
    )
    # Root-relative paths generated by PMA, including HTML attribute and CSS url().
    value = re.sub(
        r'(["\'\(])/(?!/|api/v1/plugins/hosting/sites/)(?=[\w?])',
        lambda m: m.group(1) + proxy + "/",
        value,
    )
    return value


def rewrite_location(value: str, internal: str, legacy: str, proxy: str) -> str:
    if value.startswith("/") and not value.startswith("//"):
        return proxy + value
    parsed = urlsplit(value)
    if not parsed.scheme and not value.startswith("//"):
        return value
    result = rewrite(value, internal, legacy, proxy)
    return result


def filtered_headers(
    headers: list[tuple[str, str]], internal: str, legacy: str, proxy: str
) -> dict[str, str]:
    connection = next((v for k, v in headers if k.lower() == "connection"), "")
    excluded = (
        HOP
        | {part.strip().lower() for part in connection.split(",")}
        | {
            "set-cookie",
            "x-frame-options",
            "x-content-security-policy",
            "x-webkit-csp",
        }
    )
    result: dict[str, str] = {}
    for key, value in headers:
        low = key.lower()
        if low in excluded:
            continue
        if low == "location":
            value = rewrite_location(value, internal, legacy, proxy)
        if low == "content-security-policy":
            value = re.sub(r"(?:^|;)\s*frame-ancestors\s+[^;]*", "", value, flags=re.I).strip(" ;")
            value = value + "; frame-ancestors 'self'" if value else "frame-ancestors 'self'"
        result[key] = value
    return result


class PmaClient:
    def __init__(self, url: str, timeout: int = 15) -> None:
        self.base = validate_url(url)
        self.parts = urlsplit(self.base)
        self.timeout = timeout

    def request(
        self,
        method: str,
        path: str,
        query: str = "",
        body: bytes | None = None,
        headers: dict[str, str] | None = None,
        cookies: dict[str, str] | None = None,
    ) -> tuple[http.client.HTTPConnection, http.client.HTTPResponse]:
        conn_type = (
            http.client.HTTPSConnection
            if self.parts.scheme == "https"
            else http.client.HTTPConnection
        )
        host = self.parts.hostname
        assert host is not None  # validated on construction
        conn = conn_type(host, self.parts.port, timeout=self.timeout)
        target = self.parts.path.rstrip("/") + "/" + path.lstrip("/")
        if query:
            target += "?" + query
        outgoing = {"Accept-Encoding": "identity", **(headers or {})}
        if cookies:
            outgoing["Cookie"] = "; ".join(f"{k}={v}" for k, v in cookies.items())
        try:
            conn.request(method, target, body=body, headers=outgoing)
            return conn, conn.getresponse()
        except (OSError, http.client.HTTPException) as exc:
            conn.close()
            raise AppError(
                "phpMyAdmin no responde", status_code=502, code="hosting_phpmyadmin_login_failed"
            ) from exc

    def login(self, username: str, password: str) -> dict[str, str]:
        try:
            conn, response = self.request("GET", "")
            initial = response.read(LIMIT + 1)
            cookies = merge_cookies({}, response.getheaders())
            conn.close()
            if len(initial) > LIMIT:
                raise ValueError("login form too large")
            token = re.search(rb'name=["\']token["\'][^>]*value=["\']([^"\']+)', initial)
            session = re.search(rb'name=["\']set_session["\'][^>]*value=["\']([^"\']+)', initial)
            if not token or not session:
                raise ValueError("login form missing")
            data = urlencode(
                {
                    "token": token.group(1).decode("utf-8"),
                    "set_session": session.group(1).decode("utf-8"),
                    "pma_username": username,
                    "pma_password": password,
                }
            ).encode()
            conn, response = self.request(
                "POST",
                "index.php",
                body=data,
                cookies=cookies,
                headers={"Content-Type": "application/x-www-form-urlencoded"},
            )
            body = response.read(LIMIT + 1)
            headers = response.getheaders()
            status = response.status
            conn.close()
            cookies = merge_cookies(cookies, headers)
            if status >= 400 or len(body) > LIMIT or is_login(body) or not cookies:
                raise ValueError("login rejected")
            # A redirect alone is not proof that the session was authenticated.
            conn, response = self.request("GET", "", cookies=cookies)
            dashboard = response.read(LIMIT + 1)
            cookies = merge_cookies(cookies, response.getheaders())
            verified = response.status < 400 and len(dashboard) <= LIMIT and not is_login(dashboard)
            conn.close()
            if not verified:
                raise ValueError("login rejected")
            return cookies
        except (ValueError, UnicodeError) as exc:
            raise AppError(
                "No se pudo iniciar sesión en phpMyAdmin",
                status_code=502,
                code="hosting_phpmyadmin_login_failed",
            ) from exc


def proxy_response(
    client: PmaClient,
    method: str,
    path: str,
    query: str,
    body: bytes,
    headers: dict[str, str],
    cookies: dict[str, str],
    legacy: str,
    proxy: str,
) -> tuple[Response, dict[str, str], bool]:
    conn, upstream = client.request(method, path, query, body, headers, cookies)
    raw_headers = upstream.getheaders()
    updated = merge_cookies(cookies, raw_headers)
    outgoing = filtered_headers(raw_headers, client.base, legacy, proxy)
    content_type = upstream.getheader("Content-Type", "").split(";", 1)[0].lower()
    length = upstream.getheader("Content-Length", "")
    # Login pages must not be rendered, including when an upstream session expires.
    bounded = (
        not upstream.getheader("Content-Encoding")
        and content_type in TEXT_TYPES
        and (not length or length.isdigit() and int(length) <= LIMIT)
    )
    if bounded:
        data = upstream.read(LIMIT + 1)
        if len(data) <= LIMIT:
            conn.close()
            if is_login(data):
                return (
                    Response(
                        "La sesión de phpMyAdmin expiró; volvé a abrir el modal",
                        status_code=401,
                        media_type="text/html",
                    ),
                    updated,
                    True,
                )
            # phpMyAdmin also dynamically loads this file via its JS loader;
            # stripping its HTML tag alone does not prevent top-level escape.
            if path.lstrip("/") == "js/dist/cross_framing_protection.js":
                data = b"/* framed through SPanel */"
                return Response(data, status_code=upstream.status, headers=outgoing), updated, False
            charset = re.search(r"charset=([\w-]+)", upstream.getheader("Content-Type", ""), re.I)
            encoding = charset.group(1) if charset else "utf-8"
            try:
                text = data.decode(encoding)
                if content_type == "text/html":
                    text = remove_frame_breakout(text)
                data = rewrite(text, client.base, legacy, proxy).encode(encoding)
            except (UnicodeError, LookupError):
                pass
            return Response(data, status_code=upstream.status, headers=outgoing), updated, False
        first = data
    else:
        first = b""

    def chunks() -> Iterator[bytes]:
        try:
            if first:
                yield first
            while part := upstream.read(65536):
                yield part
        finally:
            conn.close()

    return (
        StreamingResponse(chunks(), status_code=upstream.status, headers=outgoing),
        updated,
        False,
    )
